const ADMIN = process.env.ADMIN ?? 'harness-admin-token';
// Must be inside the relay's EZPDS_NOTIFY_APNS_TOPICS allowlist if that list is non-empty.
const TOPIC = process.env.TOPIC ?? 'org.obsign.identitywallet';

// The harness fronts itself with a self-signed cert.
process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';

// interop's config module reads these at first import, so set them before importing it.
process.env.EZPDS_BASE_URL = BASE;
process.env.EZPDS_ADMIN_TOKEN = ADMIN;
process.env.EZPDS_INTEROP_STATE_DIR =
  process.env.EZPDS_INTEROP_STATE_DIR ?? path.join(os.tmpdir(), 'notify-enroll-state');
process.env.EZPDS_INTEROP_PACE_MS = '25';

console.log('== 1. account ceremony (claim code → account → genesis → handle → session) ==');
const account = await import('ezpds-interop/src/account.js');
const created = await account.createAccount({ name: 'notify-enroll', kind: 'ephemeral' });
console.log(`   did:    ${created.did}`);
console.log(`   handle: ${created.handle}`);

console.log('== 2. registering a device for push ==');
// Syntactically valid stand-ins. Nothing here reaches Apple: the relay contacts APNs only
// on a push, and registration triggers none.
const res = await fetch(`${BASE}/v1/notifications/register`, {
  method: 'POST',
  headers: {
    authorization: `Bearer ${created.accessJwt}`,
    'content-type': 'application/json',
  },
  body: JSON.stringify({
    deviceUuid: '8B2F1C4E-6A3D-4F19-9C77-1E5A0D2B7F33',
    notificationPublicKey: 'did:key:REDACTED',
    apnsToken: 'REDACTED',
    apnsTopic: TOPIC,
  }),
});
console.log(`   HTTP ${res.status}: ${await res.text()}`);

